BEGIN;SET LOCAL statement_timeout='8s';SET LOCAL lock_timeout='2s';SELECT pg_advisory_xact_lock(2026083000261022);
DO $save$ DECLARE a population_top3000_202608_202609_v1.acquisition_control%rowtype; p population_top3000_202608_202609_v1.pipeline_control%rowtype;r jsonb;txt text;h text;n bigint;new_count integer:=0;new_bytes bigint:=0;ev jsonb;
