FOR r IN SELECT value FROM jsonb_array_elements('[{"source_id":"ref01-primary-issuer-excerpt:NBN:20260716:v1","source_uri":"https://investor.northeastbank.com/news-releases/news-release-details/northeast-bank-announces-dates-fiscal-2026-fourth-quarter","published_at":"2026-07-16T16:00:00Z","content":{"schema":"ref01.primary-source-facts/1","source_reference":"turn57view0","source_type":"OFFICIAL_ISSUER_PRESS_RELEASE","source_excerpt":"Northeast Bank (the “Bank”) (NASDAQ: NBN), a Maine-based bank","reported_publication":"July 16, 2026 at 12:00 PM EDT","facts":{"issuer_name":"Northeast Bank","ticker":"NBN","listing_market":"NASDAQ","issuer_type":"BANK","state":"Maine"},"extraction":"ROOT_SEMANTIC_EXTRACTION_FROM_PRIMARY_WEB_TEXT_NOT_FULL_HTML","original_wire_bytes_retained":false,"historical_received_at":null}},{"source_id":"ref01-primary-issuer-facts:NBN:20260727:v1","source_uri":"https://investor.northeastbank.com/node/16061/pdf","published_at":"2026-07-27T11:47:00Z","content":{"schema":"ref01.primary-source-facts/1","source_reference":"turn57view1 / turn58view0","source_type":"OFFICIAL_ISSUER_EARNINGS_RELEASE_PDF","reported_publication":"July 27, 2026 at 7:47 AM EDT","facts":{"issuer_name":"Northeast Bank","ticker":"NBN","listing_market":"NASDAQ","reporting_authority":"FDIC","shares_as_of":"2026-06-30","voting_common_shares_issued_and_outstanding":8555360,"nonvoting_common_shares_issued_and_outstanding":0,"preferred_shares_issued_and_outstanding":0},"table_location":"Balance sheets, PDF pages5–6; columns June30,2026 and June30,2025. Amounts in thousands except share/per-share data.","reporting_authority_location":"Forward-looking statements, PDF pages4–5.","extraction":"ROOT_SEMANTIC_EXTRACTION_FROM_PRIMARY_PDF_TEXT_NOT_FULL_PDF","original_wire_bytes_retained":false,"aug3_shares_proven":false,"aug3_cap_proven":false,"historical_received_at":null}}]'::jsonb) LOOP
txt:=(r->'content')::text;h:=encode(sha256(convert_to(txt,'UTF8')),'hex');n:=octet_length(txt);
IF a.stored_bytes+a.reserved_bytes+new_bytes+n>a.max_source_bytes THEN RAISE EXCEPTION 'SOURCE_CAP';END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.source_document d WHERE d.source_id=r->>'source_id') THEN
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.source_document d WHERE d.source_id=r->>'source_id' AND d.source_sha256=h AND d.content_text=txt AND d.source_uri=r->>'source_uri' AND d.content_bytes=n) THEN RAISE EXCEPTION 'IMMUTABLE_FACT_SOURCE_CONFLICT';END IF;
