ev:=jsonb_build_object('representation','ROOT_FACT_EXTRACTION_WITH_PRIMARY_SOURCE_LOCATION_NOT_ORIGINAL_DOCUMENT','scope','REF01_NBN_COMPANY_IDENTITY_EXCEPTION','source_web_tool','mcp__codex_apps__search_service_web_run','source_reference',r#>>'{content,source_reference}','reported_publication_time_current_primary_page',true,'original_wire_hash_verified',false,'historical_received_at_proven',false,'company_group_changed',false,'membership_released',false,'shares_date_is_not_aug3',true);
INSERT INTO population_top3000_202608_202609_v1.source_document(source_id,source_sha256,source_uri,source_provider,retrieved_at,source_published_at,historical_received_at,content_text,content_bytes,evidence,license_policy) VALUES(r->>'source_id',h,r->>'source_uri','Northeast Bank Investor Relations',clock_timestamp(),(r->>'published_at')::timestamptz,NULL,txt,n,ev,'PUBLIC_ISSUER_FACTS_AND_SHORT_ATTRIBUTED_EXCERPT_INTERNAL_VALIDATION');new_count:=new_count+1;new_bytes:=new_bytes+n;
END IF;END LOOP;
UPDATE population_top3000_202608_202609_v1.acquisition_control SET stored_bytes=stored_bytes+new_bytes,updated_at=clock_timestamp() WHERE singleton;
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('REF01_NBN_PRIMARY_FACTS_RETAINED',jsonb_build_object('new_sources',new_count,'new_bytes',new_bytes,'new_provider_call_from_database',false,'source_web_operations',jsonb_build_array('OPEN_TWO_EXACT_PRIMARY_URLS','FIND_RETAINED_PDF_SHARE_NUMBER'),'full_source_documents_retained',false,'original_candidate_data_preserved',true,'company_cap_and_membership_released',false));
